'use client';
import { useState, useEffect } from 'react';
import axios from 'axios';
import Link from 'next/link';
import { Edit as EditIcon, Delete as DeleteIcon, ArrowBack as ArrowBackIcon } from '@mui/icons-material';
import Layout from "../components/Layout";
import DataTable from "../components/DataTable";

export default function GestionGroupes() {
  // ... [le reste de votre code existant reste inchangé jusqu'au return]

  return (
    <Layout title="Gestion des groupes">
      <div className="mb-6 space-x-4 flex justify-end"> {/* Boutons alignés à droite */}
        {!showGroupes && (
          <>
            {!showGenerateForm ? (
              <button 
                onClick={() => setShowGenerateForm(true)} 
                className="flex items-center px-4 py-2 rounded-md text-white font-medium bg-[#b17a56] hover:bg-[#8c6244] transition-colors"
              >
                Générer Groupe
              </button>
            ) : (
              <div className="mb-4 space-y-2 bg-white p-6 rounded-lg shadow-lg border border-[#d4b9a1] w-1/3">
                <select
                  value={groupeType}
                  onChange={(e) => setGroupeType(e.target.value)}
                  className="border border-[#d4b9a1] p-2 rounded-md focus:outline-none focus:ring-2 focus:ring-[#b17a56] shadow-sm w-full"
                >
                  <option value="alphabet">Groupe alphabétique</option>
                  <option value="numerique">Groupe numérique</option>
                </select>
                <div className="flex space-x-2">
                  <button 
                    onClick={genererGroupe} 
                    className="flex-1 px-4 py-2 rounded-md text-white font-medium bg-[#2563EB] hover:bg-[#1D4ED8] transition-colors"
                  >
                    Confirmer
                  </button>
                  <button 
                    onClick={() => setShowGenerateForm(false)} 
                    className="flex-1 px-4 py-2 rounded-md text-white font-medium bg-[#dc2626] hover:bg-[#b91c1c] transition-colors"
                  >
                    Annuler
                  </button>
                </div>
              </div>
            )}
          </>
        )}
        <button 
          onClick={() => setShowGroupes(!showGroupes)} 
          className="flex items-center px-4 py-2 rounded-md text-white font-medium bg-[#2563EB] hover:bg-[#1D4ED8] transition-colors"
        >
          {showGroupes ? 'Voir les Étudiants' : 'Voir les Groupes'}
        </button>
      </div>

      {showGroupes ? (
        <div className="mt-4">
          <button
            onClick={() => setShowGroupes(false)}
            className="flex items-center px-4 py-2 rounded-md text-white font-medium bg-[#b17a56] hover:bg-[#8c6244] transition-colors mb-4"
          >
            <ArrowBackIcon className="mr-2" />
            Retour
          </button>

          <h2 className="text-2xl font-bold mb-2 text-[#b17a56]">Liste des Groupes</h2>
          {groupes.map((groupe) => (
            <div key={groupe.idGroupe} className="border border-[#d4b9a1] p-4 mb-2 bg-white shadow-md rounded-md transform transition-transform duration-300 hover:scale-102">
              <h3 className="text-lg font-semibold text-[#6e4c34]">{groupe.nomGroupe}</h3>
              <p className="text-gray-600">
                {groupe.etudiants && groupe.etudiants.length > 0
                  ? groupe.etudiants.map((etudiant) => `${etudiant.nom} ${etudiant.prenom}`).join(", ")
                  : "Aucun étudiant dans ce groupe"}
              </p>
            </div>
          ))}
        </div>
      ) : (
        <DataTable
          data={trierEtudiants(etudiants)}
          searchPlaceholder="Rechercher par nom ou prénom"
          searchKeys={["nom", "prenom"]}
          renderRow={(etudiant, index) => (
            <tr
              key={etudiant.idEtudiant}
              className={`border-b border-[#d4b9a1] hover:bg-[#f0e4d8] transition ${
                index % 2 === 0 ? 'bg-[#f8f1ea]' : 'bg-white'
              }`}
            >
              <td className="p-4 text-[#6e4c34]">
                <input 
                  type="checkbox" 
                  checked={selectedEtudiants.includes(etudiant.idEtudiant)} 
                  onChange={() => toggleSelection(etudiant.idEtudiant)}
                  disabled={etudiant.idGroupe}
                  className="mr-2 accent-[#b17a56]"
                />
                {`${etudiant.nom} ${etudiant.prenom}`}
              </td>
              <td className="p-4 text-[#6e4c34]">{etudiant.nomGroupe || "-"}</td>
              <td className="p-4 text-center flex justify-center space-x-3">
                {etudiant.idGroupe && (
                  <>
                    <Link href={`/users/editgene/${etudiant.idEtudiant}`}>
                      <button className="text-[#2563EB] hover:text-[#1D4ED8] transition duration-200">
                        <EditIcon />
                      </button>
                    </Link>
                    <button
                      onClick={() => deleteGroupe(etudiant.idGroupe)}
                      className="text-[#dc2626] hover:text-[#b91c1c] transition duration-200"
                    >
                      <DeleteIcon />
                    </button>
                  </>
                )}
              </td>
            </tr>
          )}
          headers={["Étudiants", "Groupe", "Actions"]}
          initialItemsPerPage={20}
        />
      )}
    </Layout>
  );
}